const inbound = $input.first();
const outer = inbound.json.body ?? inbound.json;
let payload = outer;
if (typeof outer?.metadata === 'string') payload = JSON.parse(outer.metadata);
else if (outer?.metadata && typeof outer.metadata === 'object') payload = outer.metadata;

const event = payload.event ?? payload;
const message = event.message ?? payload.message ?? event;
const rawText = String(payload.message_text ?? '').trim();
const tagMatch = rawText.match(/^#([a-z0-9-]+)\s*(?:\r?\n)?/i);
if (!tagMatch) throw new Error('缺少首行路由标签，例如 #liwei');

const analystMap = {
  liwei: 'liwei',
  liuzi: 'douyin-liuzi',
  xiaolan: 'yang-ning',
  anqiang: 'anqiang-touzi-riji',
  quanneng: 'quanneng-yeren',
};
const sourceTag = tagMatch[1].toLowerCase();
const analystId = String(payload.analyst_id ?? analystMap[sourceTag] ?? '');
if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(analystId)) throw new Error('不支持的分析师标签：#' + sourceTag);
const messageId = String(message.message_id ?? payload.message_id ?? Date.now());
const safeId = messageId.replace(/[^A-Za-z0-9_-]/g, '').slice(0, 52).padEnd(24, '0');
const resources = Array.isArray(payload.resources) ? payload.resources : [];
const content = String(payload.import_content ?? rawText.slice(tagMatch[0].length)).trim();
// content_date/content_time mean an explicit user timestamp to the remote worker.
// Receipt time is provenance, so omit both for ordinary Feishu analyst messages.
const contentDate = payload.content_date == null ? '' : String(payload.content_date);
const contentTime = payload.content_time == null ? '' : String(payload.content_time);
if ((contentDate || contentTime) && (!/^\d{4}-\d{2}-\d{2}$/.test(contentDate) || !/^\d{2}:\d{2}$/.test(contentTime))) {
  throw new Error('适配器提供的显式内容时间格式无效');
}
if (!content && !resources.length) throw new Error('标签 #' + sourceTag + ' 后没有可导入正文或媒体');
if (content && !payload.text_content_sha256) throw new Error('适配器未提供文本 SHA-256');

for (const media of resources) {
  const hasFullBinary = Boolean(inbound.binary?.[media.property]);
  const hasPartBinaries = Array.isArray(media.parts) && media.parts.length > 0 && media.parts.every((part) => Boolean(inbound.binary?.[part.property]));
  if (!hasFullBinary && !hasPartBinaries) throw new Error('飞书媒体二进制未传入 n8n：' + (media.filename ?? media.property));
}

return [{
  json: {
    analyst_id: analystId,
    topic_key: String(payload.topic_key ?? 'general'),
    publisher_key: String(payload.publisher_key ?? analystId),
    source_tag: sourceTag,
    event_id: event.event_id ?? null,
    feishu_message_id: messageId,
    batch_key: 'b_' + safeId,
    item_key: 'i_' + safeId,
    media_upload_prefix: 'u_' + safeId,
    content: content || null,
    content_sha256: content ? payload.text_content_sha256 : null,
    ...(contentDate ? { content_date: contentDate, content_time: contentTime } : {}),
    source_label: String(payload.source_label ?? (payload.source === 'manual-relay' ? '本机手动投递' : '飞书机器人')).slice(0, 120),
    media_assets: resources,
  },
  binary: inbound.binary ?? {},
}];

