const batch = $input.first().json;
const items = Array.isArray(batch.items) ? batch.items : [];
if (!items.some((item) => item.type === 'text')) {
  const addTextResult = $('HTTP Request1').first().json;
  throw new Error('远端未确认文字条目：' + JSON.stringify(addTextResult).slice(0, 500));
}
return [{ json: batch }];

const result = $input.first().json;
const batch = result.batch ?? result;
const state = String(batch.state ?? '').toLowerCase();
// The remote service exposes "queued" immediately after a successful submit.
// It is a durable acceptance state, not an upload failure.
if (!['queued', 'submitted', 'processing', 'completed', 'complete'].includes(state)) {
  throw new Error('远端批次未进入已提交状态：' + JSON.stringify(result).slice(0, 600));
}
return [{ json: result }];
